using System.Numerics;
using Ludots.Raylib.Render;
using Raylib_cs;
using Rl = Raylib_cs.Raylib;

namespace Ludots.App.RaylibEngineGallery
{
    /// <summary>
    /// 画廊共享的带光照道具通道：单一 RaylibLitModel 实例 + 昼夜光照，
    /// 供各场景把手工道具（立方体/球）从 unlit 默认材质切到 GGX + 天空 IBL 绘制。
    /// </summary>
    public sealed class GalleryLitProps : IDisposable
    {
        private readonly RaylibLitModel _lit = null!;
        private readonly RaylibFrameLighting _lighting = null!;
        private Mesh _cube;
        private Mesh _sphere;
        private bool _loaded;

        public GalleryLitProps(float dayPhase01 = 0.55f)
        {
            DayPhase01 = dayPhase01;
        }

        public float DayPhase01 { get; set; }

        public RaylibFrameLighting Lighting => _lighting;

        public RaylibLitModel Lit => _lit;

        public void Load()
        {
            if (_loaded)
            {
                return;
            }

            _lit = new RaylibLitModel();
            _lighting = RaylibFrameLighting.LoadFromDefaultPath(dayPhase01: DayPhase01);
            _cube = Rl.GenMeshCube(1f, 1f, 1f);
            _sphere = Rl.GenMeshSphere(0.5f, 24, 16);
            _loaded = true;
        }

        public void BeginFrame(Vector3 viewPos)
        {
            EnsureLoaded();
            _lighting.SetDayPhase(DayPhase01);
            _lit.BeginFrame(_lighting, viewPos);
        }

        public void DrawCube(Vector3 center, Vector3 size, Vector4 tint, float roughness = 0.8f, float metallic = 0f, float rotationYRad = 0f)
        {
            EnsureLoaded();
            Matrix4x4 rowMajor =
                Matrix4x4.CreateRotationY(rotationYRad) *
                Matrix4x4.CreateScale(size) *
                Matrix4x4.CreateTranslation(center);
            _lit.DrawMesh(_cube, RaylibMatrix.FromSystemNumerics(rowMajor), tint, roughness, metallic);
        }

        public void DrawSphere(Vector3 center, float radius, Vector4 tint, float roughness = 0.5f, float metallic = 0f)
        {
            EnsureLoaded();
            Matrix4x4 rowMajor =
                Matrix4x4.CreateScale(radius * 2f) *
                Matrix4x4.CreateTranslation(center);
            _lit.DrawMesh(_sphere, RaylibMatrix.FromSystemNumerics(rowMajor), tint, roughness, metallic);
        }

        public void Dispose()
        {
            if (!_loaded)
            {
                return;
            }

            Rl.UnloadMesh(_cube);
            Rl.UnloadMesh(_sphere);
            _lit.Dispose();
            _loaded = false;
        }

        private void EnsureLoaded()
        {
            if (!_loaded)
            {
                throw new InvalidOperationException($"{nameof(GalleryLitProps)} requires {nameof(Load)} first.");
            }
        }
    }
}

# 渲染光照栈与下游使用指南

光照栈分两条车道，合同词汇一致，按物体形态选择：

| 车道 | 适用 | 入口 |
|---|---|---|
| 合批管线 | 静态网格群 / 蒙皮人群（大量实例） | `PrimitiveDrawItem` → `RaylibPrimitiveRenderer`（`instancing` / `skinning_instanced` 着色器） |
| 单物体通道 | 道具、少量模型、验收场景陪衬 | `RaylibLitModel`（`model_lit` 着色器） |

两车道都是 **Cook-Torrance GGX 单灯 metallic-roughness** + 光照总线 `RaylibFrameLighting`（光向/环境/光色/强度/雾/视点）。

## 单物体带光照：RaylibLitModel

```csharp
var lit = new RaylibLitModel();            // LoadShader(model_lit)，uniform 合同 fail-loud
var lighting = RaylibFrameLighting.LoadFromDefaultPath(dayPhase01: 0.55f);

// 每帧一次：光照总线 + 天空半球 IBL 色
lit.BeginFrame(lighting, camera.position);

// 路径 A：共享 mesh 直接画（道具）
lit.DrawMesh(mesh, transform, tint, roughness: 0.8f, metallic: 0f);

// 路径 B：挂到模型材质，随后用标准 DrawModelEx（模型类）
lit.AttachToModel(model);
lit.ApplyDrawUniforms(tint, roughness, metallic);
Rl.DrawModelEx(model, position, axis, angle, scale, color);
```

画廊范式：`GalleryLitProps`（共享立方体/球 + 单实例）与 `GpuSkinningScene`（自有实例）。

## 平面投影阴影：RaylibPlanarShadows

```csharp
var shadows = new RaylibPlanarShadows(alpha: 110);
shadows.GroundY = 0.21f;                   // 接收平面高度（必须高于地面几何顶面）

// 模型：换装默认着色器 → planar 矩阵 → 还原
shadows.DrawModelShadow(model, position, rotationAngleY, scale, lighting.SunDirectionToward);

// mesh：
shadows.DrawMeshShadow(mesh, modelTransform, lighting.SunDirectionToward);
```

