using System.Numerics;
using Ludots.Platform.Abstractions;
using Ludots.Raylib.Render;
using Raylib_cs;
using Rl = Raylib_cs.Raylib;

namespace Ludots.App.RaylibEngineGallery.Scenes
{
    /// <summary>
    /// 大量动画实例合批：4096 具 mannequin 走环形行军——CPU 侧每帧重写变换
    /// （行军相位起伏/朝向切线/前排颜色分层），GPU 侧经 RaylibPrimitiveRenderer
    /// Instanced 车道合批绘制（每 bucket 一次 draw call）。
    /// 真骨骼逐实例蒙皮见 gpu_skinning 场景；GPU 骨骼实例化车道待 native ≥ 5.5
    /// （UpdateModelAnimationBones 导出 + Mesh boneMatrices 布局）。
    /// </summary>
    public sealed class CrowdAnimScene : IEngineScene
    {
        private const int TargetInstances = 4096;
        private const int RingCount = 14;
        private const int MannequinAssetId = 9001;

        private readonly GalleryMeshAssets _meshes = new();
        private readonly GalleryPrimitiveSnapshot _snapshot = new();
        private RaylibPrimitiveRenderer _primitives = null!;
        private RaylibFrameLighting _lighting = null!;
        private RaylibPlanarShadows _shadows = null!;
        private readonly Vector3[] _ringParams = new Vector3[TargetInstances];
        private bool _disposed;

        public string Id => "crowd_anim";
        public string Title => "大量动画实例合批";
        public string Summary => "4k mannequin 环形行军——Instanced 合批 × CPU 变换动画";

        public void Load()
        {
            _meshes.Register(
                "gallery.mannequin",
                MeshAssetDescriptor.Model(MannequinAssetId, "Models/mannequin_large_walk.glb"));
            _lighting = RaylibFrameLighting.LoadFromDefaultPath(dayPhase01: 0.58f);
            _primitives = new RaylibPrimitiveRenderer(
                RaylibPrimitiveRenderMode.Instanced,
                vfs: null,
                materials: null,
                channelRegistrar: GalleryAnimationChannels.Register);
            _shadows = new RaylibPlanarShadows(alpha: 70) { GroundY = 0.02f };

            var random = new Random(20260818);
            for (int i = 0; i < TargetInstances; i++)
            {
                int ring = i % RingCount;
                float radius = 6f + (ring * 3.1f);
                float baseAngle = (i / (float)RingCount) * MathF.Tau + (random.NextSingle() * 0.24f);
                float speed = 0.16f - (ring * 0.006f);
                _ringParams[i] = new Vector3(baseAngle, radius, speed);
            }
        }

        public void Draw(float deltaSeconds, double totalTimeSeconds, ref Camera3D camera)
        {
            GalleryCamera.EnforceDistance(ref camera, 90f);
            camera.target.Y = 3f;
            float t = (float)totalTimeSeconds;

            _lighting.SetDayPhase(0.58f);

            Rl.ClearBackground(new Color(12, 14, 20, 255));
            Rl.BeginMode3D(camera);
            Rl.DrawGrid(60, 6f);
            _primitives.ApplyFrameLighting(_lighting, camera.position);

            _snapshot.BeginFrame();
            for (int i = 0; i < TargetInstances; i++)
            {
                Vector3 p = _ringParams[i];
                float angle = p.X + (t * p.Z);
                int ring = i % RingCount;
                float phase = (angle / MathF.Tau) + (i * 0.113f);
                float bob = MathF.Abs(MathF.Sin(phase * MathF.Tau * 2f)) * 0.34f;
                float sway = MathF.Sin(phase * MathF.Tau * 2f) * 0.09f;
                Vector3 position = new(
                    MathF.Cos(angle) * p.Y,
                    bob,
                    MathF.Sin(angle) * p.Y);
                Quaternion facing = Quaternion.CreateFromYawPitchRoll(-angle - (MathF.PI * 0.5f) + sway, 0f, 0f);
                float depth = ring / (float)RingCount;
                Vector4 tint = new(0.72f - (depth * 0.2f), 0.74f - (depth * 0.12f), 0.86f - (depth * 0.28f), 1f);
                _snapshot.Add(GalleryItems.Mesh(
                    MannequinAssetId,
                    10000 + i,
                    position,
                    new Vector3(1f),
                    tint,
                    rotation: facing));
            }

            _primitives.Draw(_snapshot, camera, _meshes, timeSeconds: totalTimeSeconds);

            _shadows.DrawSphereShadow(default, 0.001f, _lighting.SunDirectionToward);
            Rl.EndMode3D();

            GalleryFont.Draw(
                $"crowd {TargetInstances} instanced  rings {RingCount}  visuals {_primitives.LastMeshVisualCount}",
                12,
                28,
                20,
                GalleryColors.RayWhite);
        }

        public void Dispose()
        {
            if (_disposed)
            {
                return;
            }

            _shadows?.Dispose();
            _primitives?.Dispose();
            _disposed = true;
        }
    }
}

using System.Numerics;
using Ludots.Platform.Abstractions;
using Ludots.Raylib.Render;
using Raylib_cs;
using Rl = Raylib_cs.Raylib;

namespace Ludots.App.RaylibEngineGallery.Scenes
{
    /// <summary>
    /// 大量动画实例合批：4096 具 mannequin 走环形行军——CPU 侧每帧重写变换
    /// （行军相位起伏/朝向切线/前排颜色分层），GPU 侧经 RaylibPrimitiveRenderer
    /// Instanced 车道合批绘制（每 bucket 一次 draw call）。
    /// 真骨骼逐实例蒙皮见 gpu_skinning 场景；GPU 骨骼实例化车道待 native ≥ 5.5
    /// （UpdateModelAnimationBones 导出 + Mesh boneMatrices 布局）。
    /// </summary>
    public sealed class CrowdAnimScene : IEngineScene
    {
        private const int TargetInstances = 4096;
        private const int RingCount = 14;
        private const int MannequinAssetId = 9001;

        private readonly GalleryMeshAssets _meshes = new();
        private readonly GalleryPrimitiveSnapshot _snapshot = new();
        private RaylibPrimitiveRenderer _primitives = null!;
        private RaylibFrameLighting _lighting = null!;
        private RaylibPlanarShadows _shadows = null!;
        private readonly Vector3[] _ringParams = new Vector3[TargetInstances];
        private bool _disposed;

        public string Id => "crowd_anim";
        public string Title => "大量动画实例合批";
        public string Summary => "4k mannequin 环形行军——Instanced 合批 × CPU 变换动画";

        public void Load()
        {
            _meshes.Register(
                "gallery.mannequin",
                MeshAssetDescriptor.Model(MannequinAssetId, "Models/mannequin_large_walk.glb"));
            _lighting = RaylibFrameLighting.LoadFromDefaultPath(dayPhase01: 0.58f);
            _primitives = new RaylibPrimitiveRenderer(
                RaylibPrimitiveRenderMode.Instanced,
                vfs: null,
                materials: null,
                channelRegistrar: GalleryAnimationChannels.Register);
            _shadows = new RaylibPlanarShadows(alpha: 70) { GroundY = 0.02f };

            var random = new Random(20260818);
            for (int i = 0; i < TargetInstances; i++)
            {
                int ring = i % RingCount;
                float radius = 6f + (ring * 3.1f);
                float baseAngle = (i / (float)RingCount) * MathF.Tau + (random.NextSingle() * 0.24f);
                float speed = 0.16f - (ring * 0.006f);
                _ringParams[i] = new Vector3(baseAngle, radius, speed);
            }
        }

        public void Draw(float deltaSeconds, double totalTimeSeconds, ref Camera3D camera)
        {
            GalleryCamera.EnforceDistance(ref camera, 90f);
            camera.target.Y = 3f;
            float t = (float)totalTimeSeconds;

            _lighting.SetDayPhase(0.58f);

            Rl.ClearBackground(new Color(12, 14, 20, 255));
            Rl.BeginMode3D(camera);
            Rl.DrawGrid(60, 6f);
            _primitives.ApplyFrameLighting(_lighting, camera.position);

            _snapshot.BeginFrame();
            for (int i = 0; i < TargetInstances; i++)
            {
                Vector3 p = _ringParams[i];
                float angle = p.X + (t * p.Z);
                int ring = i % RingCount;
                float phase = (angle / MathF.Tau) + (i * 0.113f);
                float bob = MathF.Abs(MathF.Sin(phase * MathF.Tau * 2f)) * 0.34f;
                float sway = MathF.Sin(phase * MathF.Tau * 2f) * 0.09f;
                Vector3 position = new(
                    MathF.Cos(angle) * p.Y,
                    bob,
                    MathF.Sin(angle) * p.Y);
                Quaternion facing = Quaternion.CreateFromYawPitchRoll(-angle - (MathF.PI * 0.5f) + sway, 0f, 0f);
                float depth = ring / (float)RingCount;
                Vector4 tint = new(0.72f - (depth * 0.2f), 0.74f - (depth * 0.12f), 0.86f - (depth * 0.28f), 1f);
                _snapshot.Add(GalleryItems.Mesh(
                    MannequinAssetId,
                    10000 + i,
                    position,
                    new Vector3(1f),
                    tint,
                    rotation: facing));
            }

            _primitives.Draw(_snapshot, camera, _meshes, timeSeconds: totalTimeSeconds);

            _shadows.DrawSphereShadow(default, 0.001f, _lighting.SunDirectionToward);
            Rl.EndMode3D();

            GalleryFont.Draw(
                $"crowd {TargetInstances} instanced  rings {RingCount}  visuals {_primitives.LastMeshVisualCount}",
                12,
                28,
                20,
                GalleryColors.RayWhite);
        }

        public void Dispose()
        {
            if (_disposed)
            {
                return;
            }

            _shadows?.Dispose();
            _primitives?.Dispose();
            _disposed = true;
        }
    }
}

using System.Numerics;
using Ludots.Raylib.Render;
using Raylib_cs;
using Rl = Raylib_cs.Raylib;

namespace Ludots.App.RaylibEngineGallery
{
    /// <summary>
    /// 画廊共享的带光照道具通道：单一 RaylibLitModel 实例 + 昼夜光照，
    /// 供各场景把手工道具（立方体/球）从 unlit 默认材质切到 GGX + 天空 IBL 绘制。
    /// </summary>
    public sealed class GalleryLitProps : IDisposable
    {
        private readonly RaylibLitModel _lit = null!;
        private readonly RaylibFrameLighting _lighting = null!;
        private Mesh _cube;
        private Mesh _sphere;
        private bool _loaded;

        public GalleryLitProps(float dayPhase01 = 0.55f)
        {
            DayPhase01 = dayPhase01;
        }

        public float DayPhase01 { get; set; }

        public RaylibFrameLighting Lighting => _lighting;

        public RaylibLitModel Lit => _lit;

        public void Load()
        {
            if (_loaded)
            {
                return;
            }

            _lit = new RaylibLitModel();
            _lighting = RaylibFrameLighting.LoadFromDefaultPath(dayPhase01: DayPhase01);
            _cube = Rl.GenMeshCube(1f, 1f, 1f);
            _sphere = Rl.GenMeshSphere(0.5f, 24, 16);
            _loaded = true;
        }

        public void BeginFrame(Vector3 viewPos)
        {
            EnsureLoaded();
            _lighting.SetDayPhase(DayPhase01);
            _lit.BeginFrame(_lighting, viewPos);
        }

        public void DrawCube(Vector3 center, Vector3 size, Vector4 tint, float roughness = 0.8f, float metallic = 0f, float rotationYRad = 0f)
        {
            EnsureLoaded();
            Matrix4x4 rowMajor =
                Matrix4x4.CreateRotationY(rotationYRad) *
                Matrix4x4.CreateScale(size) *
                Matrix4x4.CreateTranslation(center);
            _lit.DrawMesh(_cube, RaylibMatrix.FromSystemNumerics(rowMajor), tint, roughness, metallic);
        }

        public void DrawSphere(Vector3 center, float radius, Vector4 tint, float roughness = 0.5f, float metallic = 0f)
        {
            EnsureLoaded();
            Matrix4x4 rowMajor =
                Matrix4x4.CreateScale(radius * 2f) *
                Matrix4x4.CreateTranslation(center);
            _lit.DrawMesh(_sphere, RaylibMatrix.FromSystemNumerics(rowMajor), tint, roughness, metallic);
        }

        public void Dispose()
        {
            if (!_loaded)
            {
                return;
            }

            Rl.UnloadMesh(_cube);
            Rl.UnloadMesh(_sphere);
            _lit.Dispose();
            _loaded = false;
        }

        private void EnsureLoaded()
        {
            if (!_loaded)
            {
                throw new InvalidOperationException($"{nameof(GalleryLitProps)} requires {nameof(Load)} first.");
            }
        }
    }
}

# 渲染光照栈与下游使用指南

光照栈分两条车道，合同词汇一致，按物体形态选择：

| 车道 | 适用 | 入口 |
|---|---|---|
| 合批管线 | 静态网格群 / 蒙皮人群（大量实例） | `PrimitiveDrawItem` → `RaylibPrimitiveRenderer`（`instancing` / `skinning_instanced` 着色器） |
| 单物体通道 | 道具、少量模型、验收场景陪衬 | `RaylibLitModel`（`model_lit` 着色器） |

两车道都是 **Cook-Torrance GGX 单灯 metallic-roughness** + 光照总线 `RaylibFrameLighting`（光向/环境/光色/强度/雾/视点）。

## 单物体带光照：RaylibLitModel

```csharp
var lit = new RaylibLitModel();            // LoadShader(model_lit)，uniform 合同 fail-loud
var lighting = RaylibFrameLighting.LoadFromDefaultPath(dayPhase01: 0.55f);

// 每帧一次：光照总线 + 天空半球 IBL 色
lit.BeginFrame(lighting, camera.position);

// 路径 A：共享 mesh 直接画（道具）
lit.DrawMesh(mesh, transform, tint, roughness: 0.8f, metallic: 0f);

// 路径 B：挂到模型材质，随后用标准 DrawModelEx（模型类）
lit.AttachToModel(model);
lit.ApplyDrawUniforms(tint, roughness, metallic);
Rl.DrawModelEx(model, position, axis, angle, scale, color);
```

画廊范式：`GalleryLitProps`（共享立方体/球 + 单实例）与 `GpuSkinningScene`（自有实例）。

## 平面投影阴影：RaylibPlanarShadows

```csharp
var shadows = new RaylibPlanarShadows(alpha: 110);
shadows.GroundY = 0.21f;                   // 接收平面高度（必须高于地面几何顶面）

// 模型：换装默认着色器 → planar 矩阵 → 还原
shadows.DrawModelShadow(model, position, rotationAngleY, scale, lighting.SunDirectionToward);

// mesh：
shadows.DrawMeshShadow(mesh, modelTransform, lighting.SunDirectionToward);
```

限制：接收面为水平面（`GroundY`）；重叠投影会加深。非平面接收需等 native 升级后的 shadow map 车道。

## 材质标量 PBR 合同

材质资产 JSON（`Presentation/materials.json`）新增可选标量字段（贴图槽位不变：sourceUris[0..3] = albedo/roughness/metallic/normal，走 host_assets）：

```json
{ "id": "stone.wall", "domain": "Surface", "flags": "Opaque", "roughness": 0.7, "metalness": 0.1 }
```

- 有贴图 → 贴图优先（标量忽略）；无贴图 → 标量直达 `uRoughness`/`uMetallic`。
- 越界（非 [0,1] / 非数字）装载期 fail-loud。
- 合批管线与单物体通道同一合同（`MaterialAssetDescriptor.Roughness/Metalness`）。

## 解析式天空 IBL

`RaylibFrameLighting` 从昼夜 ramp（`ambient_day_ramp.json`）派生 `SkyZenithColor` / `SkyGroundColor`；`model_lit` 按法线朝向混合作环境漫反射、Fresnel 加权作环境镜面近似。无立方图 / LUT 依赖；昼夜联动免费获得。自定义光照时直接构造 `RaylibFrameLighting` 后调 `SetDayPhase` 即可。

## native raylib 5.0 已知限制（绕法已内建）

| 限制 | 现象 | 绕法（本栈已采用） |
|---|---|---|
| 矩阵 uniform 通道不可用（`SetShaderValueMatrix` / MAT4） | uniform 保持零矩阵 | 模型/投影矩阵一律走 `DrawModelEx`/`DrawMesh` 的 transform 原生通道 |
| GLTF 模型 mesh 按值封送布局错位 | `DrawMesh(model.meshes[i], …)` AV 崩溃 | 模型路径一律 `DrawModelEx`（内部指针布局一致） |
| `SHADER_UNIFORM_VEC4` 通道不稳 | vec4 uniform 不生效 | 着色器矩阵列用 vec3 语义（`model_lit` 不依赖 vec4 uniform） |

新增着色器时遵守：矩阵不进 uniform、模型 mesh 不按值过边界。

## 宿主接入（表现 showcase 侧）

宿主 `RaylibHostLoop` 已对地形/高度图/图元合批喂光照；单物体通道供 showcase/编辑器道具使用——构造 `RaylibLitModel` 后在 Presenter 资产绑定的模型上 `AttachToModel`，HUD/道具即携带 GGX 明暗与天空 IBL。

