using Raylib_cs;

namespace Ludots.App.RaylibEngineGallery
{
    /// <summary>
    /// 引擎画廊标准场景合同：一个能力一个场景，自含可读，零 Ludots.Core 依赖。
    /// </summary>
    public interface IEngineScene : IDisposable
    {
        string Id { get; }

        string Title { get; }

        string Summary { get; }

        /// <summary>初始化 GPU 资源；在窗口与 GL 上下文就绪后调用一次。</summary>
        void Load();

        /// <summary>每帧绘制；可调整相机（默认轨道相机由画廊提供）。</summary>
        void Draw(float deltaSeconds, double totalTimeSeconds, ref Camera3D camera);
    }
}

using System.Numerics;
using Raylib_cs;
using Rl = Raylib_cs.Raylib;

namespace Ludots.App.RaylibEngineGallery
{
    /// <summary>
    /// 画廊内置轨道相机：左键拖拽旋转、滚轮缩放、WASD/方向键平移、R 复位。
    /// </summary>
    public sealed class EngineOrbitCamera
    {
        private float _yawDeg;
        private float _pitchDeg;
        private float _distance = 40f;
        private Vector3 _target = Vector3.Zero;
        private Vector2 _lastMouse;

        public Camera3D Camera { get; private set; }

        public Vector3 Target => _target;

        public EngineOrbitCamera(float distance = 40f, float pitchDeg = 25f, float yawDeg = 45f)
        {
            _distance = distance;
            _pitchDeg = pitchDeg;
            _yawDeg = yawDeg;
            Rebuild();
        }

        public void Reset(float distance, float pitchDeg, float yawDeg, Vector3 target)
        {
            _distance = distance;
            _pitchDeg = pitchDeg;
            _yawDeg = yawDeg;
            _target = target;
            Rebuild();
        }

        public void Update(float deltaSeconds)
        {
            const float panSpeed = 18f;
            const float zoomFactor = 1.1f;

            if (Rl.IsMouseButtonDown(MouseButton.MOUSE_BUTTON_LEFT))
            {
                Vector2 mouse = Rl.GetMousePosition();
                Vector2 delta = mouse - _lastMouse;
                _yawDeg -= delta.X * 0.3f;
                _pitchDeg = Math.Clamp(_pitchDeg + delta.Y * 0.3f, 5f, 85f);
                _lastMouse = mouse;
            }
            else
            {
                _lastMouse = Rl.GetMousePosition();
            }

            float wheel = Rl.GetMouseWheelMove();
            if (wheel != 0f)
            {
                _distance = Math.Max(2f, _distance / MathF.Pow(zoomFactor, wheel));
            }

            Vector3 forward = new(
                MathF.Cos(_yawDeg * MathF.PI / 180f) * MathF.Cos(_pitchDeg * MathF.PI / 180f),
                MathF.Sin(_pitchDeg * MathF.PI / 180f),
                MathF.Sin(_yawDeg * MathF.PI / 180f) * MathF.Cos(_pitchDeg * MathF.PI / 180f));
            Vector3 flatForward = Vector3.Normalize(new Vector3(forward.X, 0f, forward.Z));
            Vector3 flatRight = new(-flatForward.Z, 0f, flatForward.X);

            if (Rl.IsKeyDown(KeyboardKey.KEY_W) || Rl.IsKeyDown(KeyboardKey.KEY_UP)) _target += flatForward * panSpeed * deltaSeconds;
            if (Rl.IsKeyDown(KeyboardKey.KEY_S) || Rl.IsKeyDown(KeyboardKey.KEY_DOWN)) _target -= flatForward * panSpeed * deltaSeconds;
            if (Rl.IsKeyDown(KeyboardKey.KEY_A) || Rl.IsKeyDown(KeyboardKey.KEY_LEFT)) _target -= flatRight * panSpeed * deltaSeconds;
            if (Rl.IsKeyDown(KeyboardKey.KEY_D) || Rl.IsKeyDown(KeyboardKey.KEY_RIGHT)) _target += flatRight * panSpeed * deltaSeconds;
            if (Rl.IsKeyPressed(KeyboardKey.KEY_R)) RebuildDefaults();

            Rebuild();
        }

        private void RebuildDefaults()
        {
            _distance = 40f;
            _pitchDeg = 25f;
            _yawDeg = 45f;
            _target = Vector3.Zero;
        }

        private void Rebuild()
        {
            Camera = new Camera3D
            {
                position = new Vector3(
                    _target.X + _distance * MathF.Cos(_yawDeg * MathF.PI / 180f) * MathF.Cos(_pitchDeg * MathF.PI / 180f),
                    _target.Y + _distance * MathF.Sin(_pitchDeg * MathF.PI / 180f),
                    _target.Z + _distance * MathF.Sin(_yawDeg * MathF.PI / 180f) * MathF.Cos(_pitchDeg * MathF.PI / 180f)),
                target = _target,
                up = Vector3.UnitY,
                fovy = 45f,
                projection = CameraProjection.CAMERA_PERSPECTIVE,
            };
        }
    }
}

using System.Diagnostics;
using System.Text;
using System.Text.Json;
using Raylib_cs;
using Rl = Raylib_cs.Raylib;

namespace Ludots.App.RaylibEngineGallery
{
    public static class Program
    {
        private const int WindowWidth = 1600;
        private const int WindowHeight = 900;

        public static int Main(string[] args)
        {
            string? sceneId = ParseOption(args, "--scene");
            string? screenshotPath = ParseOption(args, "--screenshot");
            string? jsonPath = ParseOption(args, "--json");
            int frames = ParseFrames(args);

            if (sceneId == null && screenshotPath != null)
            {
                Console.Error.WriteLine("--screenshot requires --scene <id>.");
                return 2;
            }

            if (sceneId != null && SceneCatalog.TryCreate(sceneId, out IEngineScene? scene))
            {
                return RunScene(scene!, screenshotPath, jsonPath, frames);
            }

            if (sceneId != null)
            {
                Console.Error.WriteLine($"Unknown scene '{sceneId}'. Available: {string.Join(", ", SceneCatalog.Ids)}");
                return 2;
            }

            return RunMenu();
        }

        private static int RunScene(IEngineScene scene, string? screenshotPath, string? jsonPath, int frames)
        {
            bool headless = screenshotPath != null;
            if (headless)
            {
                Rl.SetConfigFlags(ConfigFlags.FLAG_WINDOW_HIDDEN);
            }

            Rl.InitWindow(WindowWidth, WindowHeight, $"Ludots Engine Gallery — {scene.Id}");
            Rl.SetTargetFPS(60);

            var camera = new EngineOrbitCamera();
            scene.Load();

            Camera3D cam = camera.Camera;
            var frameMs = new List<double>(frames);
            var watch = Stopwatch.StartNew();
            double total = 0.0;
            int drawn = 0;

            while (drawn < frames && !Rl.WindowShouldClose())
            {
                float dt = Rl.GetFrameTime();
                total += dt;

                Rl.BeginDrawing();
                Rl.ClearBackground(Color.BLACK);

                long start = Stopwatch.GetTimestamp();
                scene.Draw(dt, total, ref cam);
                frameMs.Add((Stopwatch.GetTimestamp() - start) * 1000.0 / Stopwatch.Frequency);

                Rl.EndDrawing();
                drawn++;
            }

            int exitCode = 0;
            if (screenshotPath != null)
            {
                Directory.CreateDirectory(Path.GetDirectoryName(Path.GetFullPath(screenshotPath))!);
                Image image = Rl.LoadImageFromScreen();
                Rl.ExportImage(image, screenshotPath);
                Rl.UnloadImage(image);
                if (!File.Exists(screenshotPath))
                {
                    Console.Error.WriteLine($"Failed to write screenshot '{screenshotPath}'.");
                    exitCode = 3;
                }
            }

            if (jsonPath != null)
            {
                WriteStats(jsonPath, scene.Id, drawn, frameMs, watch.Elapsed.TotalMilliseconds);
            }

            scene.Dispose();
            Rl.CloseWindow();
            return exitCode;
        }

        private static int RunMenu()
        {
            Rl.InitWindow(WindowWidth, WindowHeight, "Ludots Engine Gallery");
            Rl.SetTargetFPS(60);

            var scenes = SceneCatalog.Descriptors;
            int selected = 0;
            int hotkey = 0;

            while (!Rl.WindowShouldClose())
            {
                for (int i = 0; i < Math.Min(scenes.Count, 36); i++)
                {
                    KeyboardKey key = HotkeyFor(i);
                    if (Rl.IsKeyPressed(key))
                    {
                        selected = i;
                        hotkey = i;
                    }
                }
                if (Rl.IsKeyPressed(KeyboardKey.KEY_ENTER) || Rl.IsKeyPressed(KeyboardKey.KEY_SPACE))
                {
                    var scene = SceneCatalog.Create(scenes[selected].Id);
                    Rl.CloseWindow();
                    return RunSceneInteractive(scene);
                }

                Rl.BeginDrawing();
                Rl.ClearBackground(new Color(18, 18, 24, 255));
                DrawMenu(scenes, selected);
                Rl.EndDrawing();
            }

            Rl.CloseWindow();
            return 0;
        }

        private static int RunSceneInteractive(IEngineScene scene)
        {
            Rl.InitWindow(WindowWidth, WindowHeight, $"Ludots Engine Gallery — {scene.Title}");
            Rl.SetTargetFPS(60);
            var camera = new EngineOrbitCamera();
            scene.Load();

            Camera3D cam = camera.Camera;
            double total = 0.0;
            while (!Rl.WindowShouldClose())
            {
                float dt = Rl.GetFrameTime();
                total += dt;
                camera.Update(dt);
                cam = camera.Camera;

                Rl.BeginDrawing();
                Rl.ClearBackground(Color.BLACK);
                scene.Draw(dt, total, ref cam);

                int y = 8;
                Rl.DrawText($"[ESC] menu   [R] reset camera", 8, WindowHeight - 26, 18, Color.RAYWHITE);
                Rl.DrawText($"{scene.Title} — {scene.Summary}", 8, WindowHeight - 48, 18, new Color(220, 220, 230, 255));
                Rl.EndDrawing();
            }

            scene.Dispose();
            Rl.CloseWindow();

            Rl.InitWindow(WindowWidth, WindowHeight, "Ludots Engine Gallery");
            Rl.SetTargetFPS(60);
            int back = RunMenu();
            return back;
        }

        private static void DrawMenu(List<SceneDescriptor> scenes, int selected)
        {
            Rl.DrawText("Ludots Engine Gallery — raylib 引擎渲染能力 18 项", 24, 20, 28, Color.RAYWHITE);
            Rl.DrawText("数字/字母选择场景，Enter 启动，ESC 退出；场景内 ESC 返回菜单，R 复位相机", 24, 56, 18, new Color(160, 160, 175, 255));

            int y = 96;
            for (int i = 0; i < scenes.Count; i++)
            {
                bool isActive = i == selected;
                Color color = isActive ? new Color(120, 220, 160, 255) : new Color(200, 200, 210, 255);
                string prefix = i < 10 ? ((i + 1) % 10).ToString() : char.ToString((char)('A' + i - 10));
                Rl.DrawText(isActive ? "> " : "  ", 24, y, 20, color);
                Rl.DrawText($"[{prefix}] {scenes[i].Title} — {scenes[i].Summary}", 52, y, 20, color);
                y += 30;
            }
        }

        private static KeyboardKey HotkeyFor(int index)
        {
            if (index < 9) return (KeyboardKey)(KeyboardKey.KEY_ONE + index);
            if (index == 9) return KeyboardKey.KEY_ZERO;
            return (KeyboardKey)(KeyboardKey.KEY_A + index - 10);
        }

        private static void WriteStats(string path, string sceneId, int frames, List<double> frameMs, double wallMs)
        {
            var ordered = frameMs.OrderBy(v => v).ToList();
            double avg = frameMs.Count > 0 ? frameMs.Average() : 0.0;
            double p95 = ordered.Count > 0 ? ordered[(int)Math.Min(ordered.Count - 1, ordered.Count * 95 / 100)] : 0.0;
            var payload = new
            {
                scene = sceneId,
                frames,
                avgFrameMs = Math.Round(avg, 3),
                p95FrameMs = Math.Round(p95, 3),
                maxFrameMs = Math.Round(frameMs.Count > 0 ? frameMs.Max() : 0.0, 3),
                wallMs = Math.Round(wallMs, 1),
            };
            Directory.CreateDirectory(Path.GetDirectoryName(Path.GetFullPath(path))!);
            File.WriteAllText(path, JsonSerializer.Serialize(payload, new JsonSerializerOptions { WriteIndented = true }));
        }

        private static string? ParseOption(string[] args, string name)
        {
            for (int i = 0; i < args.Length - 1; i++)
            {
                if (string.Equals(args[i], name, StringComparison.OrdinalIgnoreCase))
                {
                    return args[i + 1];
                }
            }
            return null;
        }

        private static int ParseFrames(string[] args)
        {
            string? value = ParseOption(args, "--frames");
            return int.TryParse(value, out int frames) && frames > 0 ? frames : 300;
        }
    }
}

