159	                        DrawArcLoop(item.Center, item.Radius * 0.33f, item.Rotation - item.Angle, item.Rotation + item.Angle, 24, ToColor(item.FillColor));
160	                        Rl.DrawLine3D(item.Center, PointOnArc(item.Center, item.Radius, item.Rotation - item.Angle), ToColor(item.BorderColor));
161	                        Rl.DrawLine3D(item.Center, PointOnArc(item.Center, item.Radius, item.Rotation + item.Angle), ToColor(item.BorderColor));
162	                        break;
163	                    case GroundOverlayShape.Line:
164	                        Vector3 end = item.Center + new Vector3(MathF.Cos(item.Rotation) * item.Length, 0f, MathF.Sin(item.Rotation) * item.Length);
165	                        Rl.DrawLine3D(item.Center, end, ToColor(item.BorderColor));
166	                        Vector3 lateral = new(-MathF.Sin(item.Rotation), 0f, MathF.Cos(item.Rotation));
167	                        Rl.DrawLine3D(item.Center + lateral * (item.Width * 0.5f), end + lateral * (item.Width * 0.5f), ToColor(item.FillColor));
168	                        Rl.DrawLine3D(item.Center - lateral * (item.Width * 0.5f), end - lateral * (item.Width * 0.5f), ToColor(item.FillColor));
169	                        break;
170	                }
171	            }
172	        }
173	
174	        private static Vector3 PointOnArc(Vector3 center, float radius, float angle)
175	        {
176	            return center + new Vector3(MathF.Cos(angle) * radius, 0f, MathF.Sin(angle) * radius);
177	        }
178	
179	        private static void DrawArcLoop(Vector3 center, float radius, float start, float end, int segments, Color color)
180	        {
181	            if (radius <= 0f)
182	            {
183	                return;
184	            }
185	
186	            float step = (end - start) / segments;
187	            for (int s = 0; s < segments; s++)
188	            {
189	                Rl.DrawLine3D(
190	                    PointOnArc(center, radius, start + (s * step)),
191	                    PointOnArc(center, radius, start + ((s + 1) * step)),
192	                    color);
193	            }
194	        }
195	
196	        private void DrawRibbons()
197	        {
198	            const int samples = 24;
199	            Span<Vector3> points = stackalloc Vector3[samples + 1];
200	            foreach (SceneRibbon ribbon in _ribbons)
201	            {
202	                for (int i = 0; i <= samples; i++)
203	                {
204	                    points[i] = EvaluateBezier(ribbon.P0, ribbon.P1, ribbon.P2, ribbon.P3, i / (float)samples);
205	                }
206	
207	                Color fill = ToColor(ribbon.Fill);
208	                int lanes = Math.Max(1, (int)MathF.Ceiling(ribbon.Width / 0.08f));
209	                for (int lane = 0; lane < lanes; lane++)
210	                {
211	                    float alpha = lanes == 1 ? 0f : lane / (float)(lanes - 1);
212	                    DrawOffsetPolyline(points, (alpha - 0.5f) * ribbon.Width, fill);
213	                }
214	
215	                Color border = ToColor(ribbon.Border);
216	                float edge = (ribbon.Width * 0.5f) + ribbon.BorderWidth;
217	                DrawOffsetPolyline(points, edge, border);
218	                DrawOffsetPolyline(points, -edge, border);
219	            }
220	        }
221	
222	        private static void DrawOffsetPolyline(ReadOnlySpan<Vector3> points, float offset, Color color)
223	        {
224	            Vector3 previous = OffsetPoint(points, 0, offset);
225	            for (int i = 1; i < points.Length; i++)
226	            {
227	                Vector3 current = OffsetPoint(points, i, offset);
228	                Rl.DrawLine3D(previous, current, color);
229	                previous = current;
230	            }
231	        }
232	
233	        private static Vector3 OffsetPoint(ReadOnlySpan<Vector3> points, int index, float offset)
234	        {
235	            Vector3 current = points[index];
236	            Vector3 forward = index == points.Length - 1
237	                ? current - points[index - 1]
238	                : points[index + 1] - current;
239	            Vector2 lateral = new(-forward.Z, forward.X);
240	            float length = lateral.Length();
241	            if (length <= 0.0001f)
242	            {
243	                return current;
244	            }
245	
246	            lateral /= length;
247	            return new Vector3(current.X + (lateral.X * offset), current.Y, current.Z + (lateral.Y * offset));
248	        }
249	
250	        private static Vector3 EvaluateBezier(in Vector3 p0, in Vector3 p1, in Vector3 p2, in Vector3 p3, float t)
251	        {
252	            float oneMinusT = 1f - t;
253	            float a = oneMinusT * oneMinusT * oneMinusT;
254	            float b = 3f * oneMinusT * oneMinusT * t;
255	            float c = 3f * oneMinusT * t * t;
256	            float d = t * t * t;
257	            return (p0 * a) + (p1 * b) + (p2 * c) + (p3 * d);
258	        }
259	
260	        private static Color ToColor(in Vector4 c)
261	        {
262	            return new Color(
263	                (byte)Math.Clamp((int)(c.X * 255f), 0, 255),
264	                (byte)Math.Clamp((int)(c.Y * 255f), 0, 255),
265	                (byte)Math.Clamp((int)(c.Z * 255f), 0, 255),
266	                (byte)Math.Clamp((int)(c.W * 255f), 0, 255));
267	        }
