115	            float[] normals =
116	            {
117	                0f, 1f, 0f, 0f, 1f, 0f, 0f, 1f, 0f,
118	                0f, 1f, 0f, 0f, 1f, 0f, 0f, 1f, 0f,
119	            };
120	            byte[] colors =
121	            {
122	                0x3D, 0xB5, 0xE0, 0x9A,
123	                0x3D, 0xB5, 0xE0, 0x9A,
124	                0x3D, 0xB5, 0xE0, 0x9A,
125	                0x3D, 0xB5, 0xE0, 0x9A,
126	                0x3D, 0xB5, 0xE0, 0x9A,
127	                0x3D, 0xB5, 0xE0, 0x9A,
128	            };
