131	            {
132	                vertexCount = 6,
133	                triangleCount = 2,
134	            };
135	            mesh.vertices = (float*)Rl.MemAlloc(sizeof(float) * vertices.Length);
136	            mesh.normals = (float*)Rl.MemAlloc(sizeof(float) * normals.Length);
