224	        private void RenderInternal(VertexMap map, in Camera3D camera, bool drawTerrain, bool drawWater, bool bumpFrame)
225	
226	        {
227	            if (map == null) return;
228	
229	            EnsureInitialized(map);
230	            UpdateUniforms(camera);
231	
232	            if (bumpFrame)
233	            {
234	                _frameIndex++;
235	                DrawnChunkCountLastFrame = 0;
236	                BuiltChunkCountLastFrame = 0;
237	                TerrainVertexCountLastFrame = 0;
238	                WaterVertexCountLastFrame = 0;
239	                ChunkBuildMsLastFrame = 0d;
240	            }
241	
242	            float cx = camera.target.X;
243	            float cz = camera.target.Z;
244	
245	            int minChunkX = (int)MathF.Floor((cx - VisibleRadius) / (HexCoordinates.HexWidth * VertexChunk.ChunkSize));
246	            int maxChunkX = (int)MathF.Ceiling((cx + VisibleRadius) / (HexCoordinates.HexWidth * VertexChunk.ChunkSize));
247	            int minChunkY = (int)MathF.Floor((cz - VisibleRadius) / (HexCoordinates.RowSpacing * VertexChunk.ChunkSize));
248	            int maxChunkY = (int)MathF.Ceiling((cz + VisibleRadius) / (HexCoordinates.RowSpacing * VertexChunk.ChunkSize));
249	
250	            minChunkX = Math.Max(0, minChunkX);
251	            minChunkY = Math.Max(0, minChunkY);
252	            maxChunkX = Math.Min(map.WidthInChunks - 1, maxChunkX);
253	            maxChunkY = Math.Min(map.HeightInChunks - 1, maxChunkY);
254	
255	            for (int y = minChunkY; y <= maxChunkY; y++)
256	            {
257	                for (int x = minChunkX; x <= maxChunkX; x++)
258	                {
259	                    long key = HexCoordinates.GetChunkKey(x, y);
260	                    float chunkWorldX = x * VertexChunk.ChunkSize * HexCoordinates.HexWidth;
261	                    float chunkWorldZ = y * VertexChunk.ChunkSize * HexCoordinates.RowSpacing;
262	                    float dx = chunkWorldX - cx;
263	                    float dz = chunkWorldZ - cz;
264	                    float dist = MathF.Sqrt(dx * dx + dz * dz);
265	
266	                    bool simplified = dist > SimplifiedCliffRadius;
267	                    ref ChunkGpu chunk = ref GetOrCreateChunk(map, x, y, simplified);
268	                    chunk.LastUsedFrame = _frameIndex;
269	
270	                    RaylibMatrix identity = RaylibMatrix.Identity;
271	                    Rl.rlDisableBackfaceCulling();
272	                    if (drawTerrain)
273	                    {
274	                        Rl.DrawMesh(chunk.TerrainMesh, _terrainMaterial, identity);
275	                        if (bumpFrame)
276	                        {
277	                            DrawnChunkCountLastFrame++;
278	                            TerrainVertexCountLastFrame += chunk.TerrainMesh.vertexCount;
279	                        }
280	                    }
281	
282	                    if (drawWater && chunk.WaterMesh.vertexCount > 0)
283	                    {
284	                        Rl.DrawMesh(chunk.WaterMesh, _waterMaterial, identity);
285	                        if (bumpFrame)
286	                        {
287	                            WaterVertexCountLastFrame += chunk.WaterMesh.vertexCount;
288	                        }
289	                    }
290	
291	                    Rl.rlEnableBackfaceCulling();
292	                }
293	            }
294	
295	            if (bumpFrame)
296	            {
297	                EvictUnusedChunks(240);
298	            }
299	        }
