395	        private ref ChunkGpu GetOrCreateChunk(VertexMap map, int chunkX, int chunkY, bool simplifiedCliffs)
396	        {
397	            long key = HexCoordinates.GetChunkKey(chunkX, chunkY);
398	            if (_chunks.TryGetValue(key, out var existing))
399	            {
400	                if (existing.SimplifiedCliffs != simplifiedCliffs)
401	                {
402	                    existing.Dispose();
403	                    _chunks.Remove(key);
404	                }
405	                else
406	                {
407	                    _chunks[key] = existing;
408	                    return ref CollectionsMarshal.GetValueRefOrNullRef(_chunks, key);
409	                }
410	            }
411	
412	            long buildStart = Stopwatch.GetTimestamp();
413	            if (_builder == null)
414	            {
415	                throw new InvalidOperationException(
416	                    $"{nameof(RaylibTerrainRenderer)} chunk build requires {nameof(EnsureInitialized)}.");
417	            }
418	
419	            _builder.BuildChunk(chunkX, chunkY, 0f, 0f, HeightScale, simplifiedCliffs, _meshData);
420	            ChunkGpu gpu = new ChunkGpu();
421	            gpu.SimplifiedCliffs = simplifiedCliffs;
422	            gpu.TerrainMesh = CreateMesh(_meshData.Terrain);
423	            gpu.WaterMesh = _meshData.Water.VertexCount > 0 ? CreateMesh(_meshData.Water) : default;
424	            gpu.LastUsedFrame = _frameIndex;
425	            BuiltChunkCountLastFrame++;
426	            ChunkBuildMsLastFrame += (Stopwatch.GetTimestamp() - buildStart) * 1000.0 / Stopwatch.Frequency;
427	            _chunks[key] = gpu;
428	            return ref CollectionsMarshal.GetValueRefOrNullRef(_chunks, key);
429	        }
