431	        private static Mesh CreateMesh(ChunkMeshWriteBuffer src)
432	        {
433	            Mesh mesh = new Mesh();
434	            mesh.vertexCount = src.VertexCount;
435	            mesh.triangleCount = src.VertexCount / 3;
436	
437	            int vFloats = src.VertexCount * 3;
438	            int cBytes = src.VertexCount * 4;
439	
440	            mesh.vertices = (float*)Rl.MemAlloc(sizeof(float) * vFloats);
441	            mesh.normals = (float*)Rl.MemAlloc(sizeof(float) * vFloats);
442	            mesh.colors = (byte*)Rl.MemAlloc(sizeof(byte) * cBytes);
443	
444	            src.Vertices.AsSpan(0, vFloats).CopyTo(new Span<float>(mesh.vertices, vFloats));
445	            src.Normals.AsSpan(0, vFloats).CopyTo(new Span<float>(mesh.normals, vFloats));
446	            src.Colors.AsSpan(0, cBytes).CopyTo(new Span<byte>(mesh.colors, cBytes));
447	
448	            Rl.UploadMesh(ref mesh, false);
449	            return mesh;
450	        }
