import io, re, subprocess
from pathlib import Path

def read(p): return io.open(p, encoding='utf-8').read()
def write(p,t): io.open(p,'w',encoding='utf-8',newline='').write(t)

# ---------- 1) WorldPlane2D 四方法迁 VisualMath ----------
wp = read('src/Core/Math/WorldPlane2D.cs')
methods = ['RadToDegValue','TransformVisualLocal','TryExtractFacingRadFromVisualYRotation','NormalizeOrIdentity']
extracted = []
for m in methods:
    # 定位 "public static ... <m>(" 方法块（花括号配平）
    start = wp.index(f'public static ')
    idx = wp.index(m, wp.index('public static'))
    # 逐个找：从每个 public static 声明行匹配方法名
    decl = None
    for mm in re.finditer(r'        public static [^\n]*\b' + m + r'\(', wp):
        decl = mm.start(); break
    assert decl is not None, m
    i = wp.index('{', decl); depth=0
    for j in range(i, len(wp)):
        if wp[j]=='{': depth+=1
        elif wp[j]=='}':
            depth-=1
            if depth==0: end=j+1; break
    # 含前面的 doc 注释（若有）
    head = wp.rfind('\n\n', 0, decl)
    block = wp[head+2:end]
    extracted.append(block)
    wp = wp[:head+2] + wp[end:]
    # 去掉可能残留的双空行
    wp = wp.replace('\n\n\n','\n\n')
write('src/Core/Math/WorldPlane2D.cs', wp)
write('src/Platform/Ludots.Platform.Abstractions/VisualMath.cs',
'using System.Numerics;\n\nnamespace Ludots.Platform.Abstractions\n{\n    public static class VisualMath\n    {\n' + '\n'.join(extracted) + '\n    }\n}\n')
