        t2 = re.sub(r'\bWorldPlane2D\.(RadToDegValue|TransformVisualLocal|TryExtractFacingRadFromVisualYRotation|NormalizeOrIdentity)\b', r'VisualMath.\1', t)
        if t2!=t:
            if 'using Ludots.Platform.Abstractions;' not in t2:
                t2 = t2.replace('namespace Ludots.', 'using Ludots.Platform.Abstractions;\n\nnamespace Ludots.', 1) if '\nnamespace' in t2 else t2
            write(f,t2); n+=1
