128	        private void DrawGroundOverlays()
129	        {
130	            const int segments = 48;
131	            foreach (GroundOverlayItem item in _overlays.GetSpan())
132	            {
133	                switch (item.Shape)
134	                {
135	                    case GroundOverlayShape.Circle:
136	                        DrawArcLoop(item.Center, item.Radius, 0f, MathF.Tau, segments, ToColor(item.FillColor));
137	                        DrawArcLoop(item.Center, item.Radius, 0f, MathF.Tau, segments, ToColor(item.BorderColor));
138	                        break;
139	                    case GroundOverlayShape.Ring:
