using System;
using System.Collections.Generic;
using System.Runtime.InteropServices;
using Raylib_cs;
using Rl = Raylib_cs.Raylib;

namespace Ludots.App.RaylibEngineGallery
{
    /// <summary>
    /// 画廊 UI 字体：默认字体仅 ASCII，中文需按码点集加载系统 CJK 字体。
    /// 码点 = ASCII + CJK 基本区 + 中文标点/全角，一次装载覆盖全部 UI 文案。
    /// </summary>
    public static unsafe class GalleryFont
    {
        private const int BaseSize = 28;
        private static Font _font;
        private static bool _loaded;

        public static void Load()
        {
            if (_loaded)
            {
                return;
            }

            string? fontPath = FindSystemCjkFont();
            if (fontPath == null)
            {
                throw new InvalidOperationException(
                    "No system CJK font found (tried simhei.ttf/msyh.ttc/simsun.ttc on Windows, Noto/WenQuanYi on Linux). Install one to render gallery UI text.");
            }

            List<int> codepoints = BuildCodepoints();
            int[] array = codepoints.ToArray();
            fixed (int* ptr = array)
            {
                _font = Rl.LoadFontEx(fontPath, BaseSize, ptr, array.Length);
            }

            if (_font.atlas.id == 0 || _font.glyphCount == 0)
            {
                throw new InvalidOperationException($"Failed to load CJK glyphs from '{fontPath}'.");
            }

            _loaded = true;
        }

        public static void Draw(string text, int x, int y, float size, Color color)
        {
            EnsureLoaded();
            Rl.DrawTextEx(_font, text, new System.Numerics.Vector2(x, y), size, 1f, color);
        }

        public static void Unload()
        {
            if (_loaded)
            {
                Rl.UnloadFont(_font);
                _loaded = false;
            }
        }

        private static void EnsureLoaded()
        {
            if (!_loaded)
            {
                throw new InvalidOperationException($"{nameof(GalleryFont)} requires {nameof(Load)} after window init.");
            }
        }

        private static string? FindSystemCjkFont()
        {
            if (RuntimeInformation.IsOSPlatform(OSPlatform.Windows))
            {
                string fontsRoot = Environment.GetFolderPath(Environment.SpecialFolder.Fonts);
                if (string.IsNullOrEmpty(fontsRoot))
                {
                    fontsRoot = PathCombine("C:", "Windows", "Fonts");
                }

                foreach (string name in new[] { "simhei.ttf", "msyh.ttc", "msyhbd.ttc", "simsun.ttc" })
                {
                    string candidate = PathCombine(fontsRoot, name);
                    if (File.Exists(candidate))
                    {
                        return candidate;
                    }
                }

                return null;
            }

            string[] linuxCandidates =
            {
                "/usr/share/fonts/opentype/noto/NotoSansCJK-Regular.ttc",
                "/usr/share/fonts/truetype/wqy/wqy-microhei.ttc",
                "/usr/share/fonts/noto-cjk/NotoSansCJK-Regular.ttc",
            };
            foreach (string candidate in linuxCandidates)
            {
                if (File.Exists(candidate))
                {
                    return candidate;
                }
            }

            return null;
        }

        private static List<int> BuildCodepoints()
        {
            var codepoints = new List<int>(32 + 128 - 32);
            for (int c = 32; c < 127; c++)
            {
                codepoints.Add(c);
            }

            for (int c = 0x3000; c <= 0x303F; c++)
            {
                codepoints.Add(c);
            }

            for (int c = 0x4E00; c <= 0x9FA5; c++)
            {
                codepoints.Add(c);
            }

            for (int c = 0xFF00; c <= 0xFF5F; c++)
            {
                codepoints.Add(c);
            }

            return codepoints;
        }

        private static string PathCombine(params string[] parts)
        {
            return string.Join(System.IO.Path.DirectorySeparatorChar.ToString(), parts);
        }
    }
}

