#version 330

in vec3 vertexPosition;
in vec2 vertexTexCoord;
in vec3 vertexNormal;

uniform mat4 mvp;
uniform mat4 model;

out vec2 fragTexCoord;
out vec3 fragNormal;
out vec3 fragPos;

void main()
{
    fragTexCoord = vertexTexCoord;
    fragNormal = normalize(mat3(model) * vertexNormal);
    fragPos = vec3(model * vec4(vertexPosition, 1.0));
    gl_Position = mvp * vec4(vertexPosition, 1.0);
}

#version 330

in vec2 fragTexCoord;
in vec3 fragNormal;
in vec3 fragPos;
out vec4 finalColor;

uniform sampler2D texture0;
uniform vec4 colDiffuse;
uniform vec4 tint;
uniform vec3 uLightDir;
uniform vec4 uAmbient;
uniform vec3 uLightColor;
uniform float uLightIntensity;
uniform vec3 uViewPos;
uniform vec3 uFogColor;
uniform vec4 uFogParams;
uniform float uRoughness;
uniform float uMetallic;
uniform vec3 uSkyZenith;
uniform vec3 uSkyGround;
uniform sampler2D uShadowMap;
uniform mat4 uLightSpaceMatrix;
uniform float uShadowEnabled;
uniform float uShadowTexelWorld;
uniform float uShadowRadius;

const float PI = 3.14159265359;
const float MIN_ROUGHNESS = 0.04;

float DistanceFogAmount(float dist)
{
    if (uFogParams.w < 0.5)
    {
        return 0.0;
    }

    float start = uFogParams.y;
    float end = uFogParams.z;
    float linear = clamp((dist - start) / max(end - start, 1e-5), 0.0, 1.0);
    float density = uFogParams.x;
    if (density <= 0.0)
    {
        return linear;
    }

    float d = max(dist - start, 0.0);
    float expFog = 1.0 - exp(-density * d);
    return clamp(max(linear, expFog), 0.0, 1.0);
}

float DistributionGGX(vec3 N, vec3 H, float roughness)
{
    float a = roughness * roughness;
    float a2 = a * a;
    float NdotH = max(dot(N, H), 0.0);
    float NdotH2 = NdotH * NdotH;
    float denom = (NdotH2 * (a2 - 1.0) + 1.0);
    return a2 / max(PI * denom * denom, 1e-6);
}

float GeometrySchlickGGX(float NdotX, float roughness)
{
    float r = roughness + 1.0;
    float k = (r * r) / 8.0;
    return NdotX / max(NdotX * (1.0 - k) + k, 1e-6);
}

float GeometrySmith(vec3 N, vec3 V, vec3 L, float roughness)
{
    return GeometrySchlickGGX(max(dot(N, V), 0.0), roughness) *
           GeometrySchlickGGX(max(dot(N, L), 0.0), roughness);
}

vec3 FresnelSchlick(float cosTheta, vec3 F0)
{
    return F0 + (1.0 - F0) * pow(clamp(1.0 - cosTheta, 0.0, 1.0), 5.0);
}

// RGBA 打包线性深度（[0,1]×256 进位），规避无深度格式绑定的限制
float UnpackDepth(vec4 packed)
{
    return dot(packed, vec4(1.0, 1.0 / 255.0, 1.0 / 65025.0, 1.0 / 16581375.0));
}

float SampleShadow(vec3 worldPos, vec3 N)
{
    if (uShadowEnabled < 0.5)
    {
        return 1.0;
    }

    // 沿法线偏移世界坐标再投影，抑制自遮挡痤疮
    vec3 offsetPos = worldPos + N * uShadowTexelWorld;
    vec4 lightSpace = uLightSpaceMatrix * vec4(offsetPos, 1.0);
    vec3 proj = lightSpace.xyz / max(lightSpace.w, 1e-6);
    proj = proj * 0.5 + 0.5;
    if (proj.x < 0.0 || proj.x > 1.0 || proj.y < 0.0 || proj.y > 1.0 || proj.z > 1.0)
    {
        return 1.0;
    }

    float receiverDepth = proj.z;
    float texel = 1.0 / 2048.0;
    float lit = 0.0;
    int taps = 0;
    for (int y = -1; y <= 1; y++)
    {
        for (int x = -1; x <= 1; x++)
        {
            float stored = UnpackDepth(texture(uShadowMap, proj.xy + vec2(x, y) * texel));
            lit += receiverDepth <= stored + 0.0015 ? 1.0 : 0.0;
            taps++;
        }
    }

    return lit / taps;
}

void main()
{
    vec4 albedoSample = texture(texture0, fragTexCoord) * colDiffuse * tint;
    vec3 albedo = albedoSample.rgb;

    float roughness = clamp(uRoughness, MIN_ROUGHNESS, 1.0);
    float metallic = clamp(uMetallic, 0.0, 1.0);

    vec3 N = normalize(fragNormal);
    vec3 V = normalize(uViewPos - fragPos);
    vec3 L = normalize(uLightDir);
    vec3 H = normalize(V + L);

    float NdotL = max(dot(N, L), 0.0);
    vec3 F0 = mix(vec3(0.04), albedo, metallic);
    float D = DistributionGGX(N, H, roughness);
    float G = GeometrySmith(N, V, L, roughness);
    vec3 F = FresnelSchlick(max(dot(H, V), 0.0), F0);
    vec3 specular = (D * G * F) / max(4.0 * max(dot(N, V), 0.0) * NdotL, 1e-5);

    // 解析式天空 IBL：半球环境色（天顶/地面）按法线朝向混合作环境漫反射，
    // 同色经 Fresnel 加权作环境镜面近似——从昼夜 ramp 派生，无立方图/LUT 依赖。
    float hemisphere = N.y * 0.5 + 0.5;
    vec3 skyIrradiance = mix(uSkyGround, uSkyZenith, hemisphere);
    vec3 kSAmbient = F0 + (vec3(1.0) - F0) * pow(clamp(1.0 - max(dot(N, V), 0.0), 0.0, 1.0), 5.0);
    vec3 ambientDiffuse = skyIrradiance * albedo * (1.0 - metallic);
    vec3 ambientSpecular = skyIrradiance * kSAmbient * (1.0 - roughness) * 0.5;
    vec3 ambient = ambientDiffuse + ambientSpecular + uAmbient.rgb * uAmbient.a * albedo;

    float shadow = SampleShadow(fragPos, N);
    vec3 kS = F;
    vec3 kD = (vec3(1.0) - kS) * (1.0 - metallic);
    vec3 radiance = uLightColor * uLightIntensity;
    vec3 litColor = ambient + (kD * albedo / PI + specular) * radiance * NdotL * shadow;

    float fogAmount = DistanceFogAmount(length(fragPos - uViewPos));
    vec3 fogged = mix(litColor, uFogColor, fogAmount);
    finalColor = vec4(clamp(fogged, 0.0, 1.0), albedoSample.a);
}

#version 330

in vec3 vertexPosition;

uniform mat4 mvp;

out float fragViewZ;

void main()
{
    gl_Position = mvp * vec4(vertexPosition, 1.0);
    fragViewZ = gl_Position.z;
}

#version 330

in float fragViewZ;
out vec4 finalColor;

// 线性深度 [0,1] RGBA 打包（256 进位），model_lit.fs UnpackDepth 对应解码
void main()
{
    float depth = clamp(fragViewZ * 0.5 + 0.5, 0.0, 1.0);
    vec4 packed = vec4(depth, fract(depth * 255.0), fract(depth * 65025.0), fract(depth * 16581375.0));
    packed.xyz -= packed.yzw / 255.0;
    finalColor = packed;
}

#version 330

in vec3 vertexPosition;

uniform mat4 mvp;

void main()
{
    gl_Position = mvp * vec4(vertexPosition, 1.0);
}

#version 330

out vec4 finalColor;

// 硬件深度 gl_FragCoord.z（[0,1]）RGBA 256 进位打包，model_lit.fs UnpackDepth 对应解码
void main()
{
    float depth = gl_FragCoord.z;
    vec4 enc = vec4(1.0, 255.0, 65025.0, 16581375.0) * depth;
    enc = fract(enc);
    enc -= enc.yzww * vec4(1.0 / 255.0, 1.0 / 255.0, 1.0 / 255.0, 0.0);
    finalColor = enc;
}

